-- The students who have signed in, and what they answered.
-- The words themselves live in the teacher's sheet; an attempt keeps a copy of
-- the word so it stays readable after the sheet is edited.

CREATE TABLE student (
    id         BIGSERIAL PRIMARY KEY,
    email      TEXT        NOT NULL,
    name       TEXT        NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT student_email_unique UNIQUE (email),
    CONSTRAINT student_email_lowercase CHECK (email = lower(email))
);

CREATE TABLE attempt (
    -- Generated by the client, so uploading the same attempt twice is harmless.
    id          UUID PRIMARY KEY,
    student_id  BIGINT      NOT NULL REFERENCES student (id),
    deck_id     TEXT        NOT NULL,
    deck_name   TEXT        NOT NULL,
    word_id     TEXT        NOT NULL,
    english     TEXT        NOT NULL,
    hungarian   TEXT        NOT NULL,
    mode        TEXT        NOT NULL,
    outcome     TEXT        NOT NULL,
    -- When the student answered (the phone's time) and when the server got it.
    answered_at TIMESTAMPTZ NOT NULL,
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT attempt_mode_known
        CHECK (mode IN ('FLASHCARDS', 'MATCHING', 'QUIZ', 'TYPING', 'MIX')),
    CONSTRAINT attempt_outcome_known
        CHECK (outcome IN ('FIRST_TRY', 'WITH_HELP', 'WRONG_FIRST'))
);

CREATE INDEX attempt_student_answered_idx ON attempt (student_id, answered_at);
CREATE INDEX attempt_student_word_idx ON attempt (student_id, deck_id, word_id);
